insert into public.plans (key, name, description) values ('free', 'Free', 'Game 1 and your statue, free forever.') on conflict (key) do nothing;
insert into public.entitlements (plan_id, feature_key, limit_value) values ((select id from public.plans where key = 'free'), 'statue_rerolls', 1) on conflict (plan_id, feature_key) do nothing;
insert into public.plans (key, name, description) values ('pro', 'Pro', 'Extra statue re-rolls and Pro perks.') on conflict (key) do nothing;
insert into public.entitlements (plan_id, feature_key, limit_value) values ((select id from public.plans where key = 'pro'), 'statue_rerolls', 5) on conflict (plan_id, feature_key) do nothing;
insert into public.games (slug, title, type, status, config) values ('g1', 'Self-Development', 'free', 'active', '{"id":"g1","title":"Self-Development","worlds":{"inner":{"name":"The Inner World","description":"internal self-control, thoughts and health."},"outer":{"name":"The Outer World","description":"external lifestyle, environment and daily choices."}},"pillars":[{"id":"mental","world":"inner","name":"Mental","covers":"focus, learning new skills, controlling thoughts, a growth mindset."},{"id":"physical","world":"inner","name":"Physical","covers":"nutrition, exercise, consistent sleep, daily energy."},{"id":"emotional","world":"inner","name":"Emotional","covers":"emotional intelligence, processing feelings, responding rather than reacting."},{"id":"spiritual","world":"inner","name":"Spiritual","covers":"core values, sense of purpose, deeper meaning."},{"id":"financial","world":"outer","name":"Financial","covers":"managing, saving and investing money; career growth and stability."},{"id":"social","world":"outer","name":"Social","covers":"relationship quality, communication, boundaries."},{"id":"environmental","world":"outer","name":"Environmental","covers":"organized home and workspace, minimal digital clutter."},{"id":"recreational","world":"outer","name":"Recreational","covers":"hobbies, play, relaxation, breaks from work."}],"ramp":[{"id":"initiate","fromWeek":1,"overrides":{"g1.read":{"targets":{"targetPages":5}},"g1.exercise":{"perWeek":2},"g1.dawn":{"perWeek":2}}},{"id":"apprentice","fromWeek":2,"overrides":{"g1.read":{"targets":{"targetPages":10}},"g1.exercise":{"perWeek":3},"g1.dawn":{"perWeek":3},"g1.stillness":{"perWeek":3}}},{"id":"adept","fromWeek":3,"overrides":{"g1.exercise":{"perWeek":4},"g1.dawn":{"perWeek":4},"g1.stillness":{"perWeek":5},"g1.money":{"perWeek":3},"g1.connect":{"perWeek":2}}},{"id":"full_protocol","fromWeek":4}],"bonusXp":{"fullSet":25,"innerBalance":50,"outerBalance":50,"balancedWeek":100,"perfectWeek":250},"books":{"questId":"g1.read","pagesField":"pages","bookIdField":"bookId","finishedXp":150},"eventDecorations":{"perfect_week":"gold_vein","book_finished":"laurel_leaf","balanced_week":"plinth_carving"},"feedsSculpture":true}'::jsonb) on conflict (slug) do nothing;
insert into public.quests (game_id, key, pillar, title, founding, schedule, "window", proof, xp, unlock, sort_order) values ((select id from public.games where slug = 'g1'), 'g1.read', 'mental', 'Read 10 pages a day from a self-development book', true, '{"kind":"daily"}'::jsonb, '{"kind":"anytime"}'::jsonb, '{"type":"reading","targetPages":10}'::jsonb, 20, '{"kind":"ramp_stage","atLeast":"initiate"}'::jsonb, 1) on conflict (game_id, key) do nothing;
